from taf.hw.hp.redfish.httpclient.ApiClient import ApiClient
from taf.hw.hp.redfish.httpclient.redfish_uri import TaskServiceURI


class TaskCommon(object):
    def __init__(self, configuration, access_token):
        self.httpclient = ApiClient(configuration, access_token)

    def get_task_status(self, task_id, check_status=None):
        uri = TaskServiceURI().task_status_uri.format(task_id=task_id)
        result = self.httpclient.send_get_request(uri=uri, check_status=check_status)
        return result["TaskState"]
